-- R8 audited onboarding lifecycle persistence.
CREATE OR REPLACE FUNCTION public.mmhr_record_onboarding(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE context record; receipt jsonb; onboarding public.onboarding_plans%ROWTYPE; v_org uuid; v_actor uuid; v_id uuid; v_deal uuid; v_action text; v_from text; v_to text; v_expected integer; v_reason text; v_failure text; v_approval uuid; v_occurred timestamptz; milestone jsonb;
BEGIN
 IF jsonb_typeof(payload)<>'object' OR coalesce(payload->>'action','') NOT IN ('create','transition') OR coalesce(payload->>'onboardingId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR correlation_id IS NULL OR idempotency_key IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid onboarding input'; END IF;
 v_action:=payload->>'action'; v_org:=(payload->>'organizationId')::uuid; v_actor:=(payload->>'actorIdentityId')::uuid; v_id:=(payload->>'onboardingId')::uuid; SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access',v_org,'Record onboarding',correlation_id,idempotency_key); IF v_actor<>context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Security command denied'; END IF; receipt:=mmhr_private.r1_checked_receipt(context.actor_identity_id,'r8.onboarding',idempotency_key,payload); IF receipt IS NOT NULL THEN RETURN jsonb_build_object('onboardingId',receipt->>'entity_id','organizationId',v_org,'outcomeCode','replayed','correlationId',correlation_id); END IF;
 IF v_action='create' THEN
   IF coalesce(payload->>'dealId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'ownerIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR (payload->>'targetGoLiveAt')::timestamptz IS NULL OR jsonb_typeof(payload->'milestones')<>'array' OR jsonb_array_length(payload->'milestones') NOT BETWEEN 1 AND 200 OR jsonb_typeof(coalesce(payload->'checkIns','[]'::jsonb))<>'array' OR jsonb_typeof(coalesce(payload->'risks','[]'::jsonb))<>'array' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid onboarding create'; END IF;
   v_deal:=(payload->>'dealId')::uuid; IF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=v_deal AND organization_id=v_org) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Onboarding deal denied'; END IF;
   INSERT INTO public.onboarding_plans(id,organization_id,deal_id,owner_identity_id,target_go_live_at,status,revision,milestones,check_ins,risks,created_at,updated_at) VALUES(v_id,v_org,v_deal,(payload->>'ownerIdentityId')::uuid,(payload->>'targetGoLiveAt')::timestamptz,'planned',1,payload->'milestones',coalesce(payload->'checkIns','[]'::jsonb),coalesce(payload->'risks','[]'::jsonb),clock_timestamp(),clock_timestamp()) RETURNING * INTO onboarding;
 ELSE
   IF coalesce(payload->>'fromStatus','') NOT IN ('planned','active','at_risk','failed','reactivated','completed','cancelled') OR coalesce(payload->>'toStatus','') NOT IN ('planned','active','at_risk','failed','reactivated','completed','cancelled') OR coalesce((payload->>'expectedRevision')::integer,0)<=0 OR length(btrim(coalesce(payload->>'reason',''))) NOT BETWEEN 1 AND 2000 OR (payload->>'occurredAt')::timestamptz IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid onboarding transition'; END IF;
   v_from:=payload->>'fromStatus'; v_to:=payload->>'toStatus'; v_expected:=(payload->>'expectedRevision')::integer; v_reason:=btrim(payload->>'reason'); v_failure=NULLIF(btrim(coalesce(payload->>'failureReason','')),''); v_approval=NULLIF(payload->>'approvalReference','')::uuid; v_occurred:=(payload->>'occurredAt')::timestamptz;
   SELECT * INTO onboarding FROM public.onboarding_plans WHERE id=v_id AND organization_id=v_org FOR UPDATE; IF NOT FOUND OR onboarding.status<>v_from OR onboarding.revision<>v_expected THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Onboarding transition denied'; END IF;
   IF NOT ((v_from='planned' AND v_to IN ('active','cancelled')) OR (v_from='active' AND v_to IN ('at_risk','failed','completed','cancelled')) OR (v_from='at_risk' AND v_to IN ('active','failed','completed','cancelled')) OR (v_from='failed' AND v_to IN ('reactivated','cancelled')) OR (v_from='reactivated' AND v_to IN ('active','at_risk','failed','completed','cancelled'))) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Onboarding transition not allowed'; END IF;
   IF v_to='failed' AND v_failure IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Failed onboarding requires a reason'; END IF; IF v_to='reactivated' AND v_approval IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Onboarding reactivation requires approval'; END IF;
   IF v_to='completed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(onboarding.milestones) item(value) WHERE item.value->>'status' IN ('pending','in_progress','blocked')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Onboarding milestones incomplete'; END IF;
   UPDATE public.onboarding_plans SET status=v_to,revision=revision+1,failure_reason=CASE WHEN v_to IN ('failed','reactivated') THEN coalesce(v_failure,failure_reason) ELSE NULL END,reactivated_from_revision=CASE WHEN v_to='reactivated' THEN revision ELSE NULL END,updated_at=clock_timestamp() WHERE id=v_id AND organization_id=v_org RETURNING * INTO onboarding;
   INSERT INTO public.onboarding_history(id,organization_id,onboarding_id,from_status,to_status,expected_revision,actor_identity_id,reason,approval_reference,occurred_at,correlation_id) VALUES(gen_random_uuid(),v_org,v_id,v_from,v_to,v_expected,v_actor,v_reason,v_approval,v_occurred,correlation_id);
 END IF;
 PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id,'r8.onboarding','onboarding.'||v_action,'onboarding_plan',onboarding.id,v_org,'Record onboarding',correlation_id,idempotency_key,payload,jsonb_build_object('status','completed'),jsonb_build_object('status','completed'),context.authorization_time);
 RETURN jsonb_build_object('onboardingId',onboarding.id,'organizationId',onboarding.organization_id,'status',onboarding.status,'revision',onboarding.revision,'outcomeCode','recorded','correlationId',correlation_id);
END; $$;
REVOKE ALL ON FUNCTION public.mmhr_record_onboarding(jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role,mmhr_worker; GRANT EXECUTE ON FUNCTION public.mmhr_record_onboarding(jsonb,uuid,uuid) TO authenticated;
